import{_ as d,o as e,c as o,a5 as c}from"./chunks/framework.BqnnR8ku.js";const p=JSON.parse('{"title":"管理员后台","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/admin.md","filePath":"zh/guide/admin.md"}'),a={name:"zh/guide/admin.md"};function r(i,t,s,l,n,h){return e(),o("div",null,[...t[0]||(t[0]=[c('<h1 id="管理员后台" tabindex="-1">管理员后台 <a class="header-anchor" href="#管理员后台" aria-label="Permalink to &quot;管理员后台&quot;">​</a></h1><p>服务器模式下，LinguaFlow 提供一套管理员接口与界面，用于多用户管理、系统监控与操作审计。本地模式为单用户，无需管理员能力，本页内容不适用。</p><div class="tip custom-block"><p class="custom-block-title">适用范围</p><p>管理员后台仅在<strong>服务器模式</strong>（<code>linguaflow serve</code>）下可用。本地模式自动以 <code>local</code> 用户身份运行，不存在多用户场景。</p></div><h2 id="成为管理员" tabindex="-1">成为管理员 <a class="header-anchor" href="#成为管理员" aria-label="Permalink to &quot;成为管理员&quot;">​</a></h2><p>管理员的判定是用户表中的 <code>role</code> 字段为 <code>admin</code>。获得管理员身份的方式：</p><ul><li><strong>启动时指定</strong>：通过环境变量 <code>LINGUAFLOW_ADMIN_USERNAME</code> / <code>LINGUAFLOW_ADMIN_PASSWORD</code> 在首次启动时创建初始管理员账户（详见 <a href="/LinguaFlow/zh/guide/modes.html#管理员配置">使用模式 · 管理员配置</a>）。</li><li><strong>自动提升</strong>：未设置上述环境变量时，若 <code>registration.auto_admin</code> 为 <code>true</code>（默认），首个注册的用户自动成为管理员。</li><li><strong>既有管理员授权</strong>：已登录的管理员可在用户管理中把其他用户的角色改为 <code>admin</code>。</li></ul><div class="warning custom-block"><p class="custom-block-title">末位管理员保护</p><p>系统不允许移除最后一个活跃管理员账户。下列操作会被拒绝并返回 <code>409 conflict</code>：</p><ul><li>把唯一活跃管理员的角色降级为 <code>user</code></li><li>停用唯一活跃管理员账户</li></ul></div><p>此外，管理员<strong>不能修改自己的角色</strong>、<strong>不能停用自己的账户</strong>，避免误锁自己出局。</p><h2 id="用户管理" tabindex="-1">用户管理 <a class="header-anchor" href="#用户管理" aria-label="Permalink to &quot;用户管理&quot;">​</a></h2><p>管理员可以管理服务器上的全部用户：</p><table tabindex="0"><thead><tr><th>操作</th><th>说明</th></tr></thead><tbody><tr><td>列出用户</td><td>支持按用户名 / 邮箱搜索、按角色筛选、按启用状态筛选，分页返回</td></tr><tr><td>查看用户</td><td>获取单个用户的资料与角色</td></tr><tr><td>创建用户</td><td>直接创建账户（绕过注册流程），可指定 <code>role</code> 为 <code>user</code> 或 <code>admin</code></td></tr><tr><td>更新用户</td><td>修改显示名、邮箱、角色、启用状态</td></tr><tr><td>停用用户</td><td>软删除：置 <code>active=false</code>，账户无法再登录，但历史数据保留</td></tr><tr><td>重置密码</td><td>为用户设置新密码（最少 8 位）</td></tr></tbody></table><p>创建用户与重置密码时，密码长度至少 8 位，邮箱需包含 <code>@</code>。用户名重复会返回 <code>409 conflict</code>。</p><p>对应接口见本页 <a href="#api-速览">API 速览</a>。</p><h2 id="系统统计" tabindex="-1">系统统计 <a class="header-anchor" href="#系统统计" aria-label="Permalink to &quot;系统统计&quot;">​</a></h2><p><code>/admin/stats</code> 返回全平台的聚合指标，用于了解整体规模：</p><table tabindex="0"><thead><tr><th>字段</th><th>含义</th></tr></thead><tbody><tr><td><code>total_users</code></td><td>用户总数</td></tr><tr><td><code>active_users</code></td><td>启用中的用户数</td></tr><tr><td><code>total_projects</code></td><td>项目总数</td></tr><tr><td><code>total_organizations</code></td><td>组织总数</td></tr><tr><td><code>total_jobs</code></td><td>作业总数</td></tr><tr><td><code>total_resources</code></td><td>资源文件总数</td></tr></tbody></table><p>该接口为全局视角，不按用户 / 组织隔离；个人视角的用量（API 调用、Token 消耗等）走 <code>/stats/summary</code>。</p><h2 id="审计日志" tabindex="-1">审计日志 <a class="header-anchor" href="#审计日志" aria-label="Permalink to &quot;审计日志&quot;">​</a></h2><p>审计日志记录平台上的关键写操作：谁（actor）、在何时、对什么资源（resource_type / resource_id）、做了什么（action）。每条记录还附带人类可读的 <code>message</code> 与结构化 <code>metadata</code>。</p><p>LinguaFlow 区分两套活动视图：</p><table tabindex="0"><thead><tr><th>视图</th><th>接口</th><th>可见范围</th><th>用途</th></tr></thead><tbody><tr><td><strong>个人活动</strong></td><td><code>GET /api/v1/activity</code></td><td>仅本人发起的、或属于其所在组织 / 项目的活动</td><td>普通用户回顾自己的操作</td></tr><tr><td><strong>全局审计</strong></td><td><code>GET /api/v1/admin/audit-logs</code></td><td>全部活动记录</td><td>管理员排查、合规追溯</td></tr></tbody></table><p>两者返回结构一致（<code>Activity</code> 模型），但个人活动接口按当前用户的可见范围过滤，全局审计接口需管理员权限。Web 界面在仪表盘展示个人活动，管理员后台展示全局审计日志。</p><h3 id="分页" tabindex="-1">分页 <a class="header-anchor" href="#分页" aria-label="Permalink to &quot;分页&quot;">​</a></h3><p>两个接口都采用基于记录 <code>id</code> 的<strong>反向游标分页</strong>（最新在前）：</p><table tabindex="0"><thead><tr><th>参数</th><th>说明</th></tr></thead><tbody><tr><td><code>limit</code></td><td>每页条数，<code>1</code>–<code>100</code>，默认 <code>50</code></td></tr><tr><td><code>cursor</code></td><td>上一页最后一条的 <code>id</code>；省略时从最新一页开始</td></tr></tbody></table><p>请求下一页时，把当前页最后一条的 <code>id</code> 作为 <code>cursor</code> 传入即可。<code>/activity</code> 的响应中还会给出 <code>next_cursor</code> 字符串游标，可直接透传。</p><h3 id="动作类型" tabindex="-1">动作类型 <a class="header-anchor" href="#动作类型" aria-label="Permalink to &quot;动作类型&quot;">​</a></h3><p>下表列出后端实际记录的 <code>action</code> 值。前端会按这些键做颜色分类与中文标签映射；直接消费 API 时可参照下表理解。</p><table tabindex="0"><thead><tr><th><code>action</code></th><th>触发场景</th><th>资源类型</th></tr></thead><tbody><tr><td><code>job.create</code></td><td>创建翻译作业</td><td><code>job</code></td></tr><tr><td><code>job.cancel</code></td><td>取消作业</td><td><code>job</code></td></tr><tr><td><code>job.retry</code></td><td>重试作业</td><td><code>job</code></td></tr><tr><td><code>segment.approve</code></td><td>审校通过单个段落</td><td><code>segment</code></td></tr><tr><td><code>segment.reject</code></td><td>审校驳回单个段落</td><td><code>segment</code></td></tr><tr><td><code>segment.batch_review</code></td><td>批量审核段落</td><td><code>resource</code></td></tr><tr><td><code>segment.approve_all</code></td><td>一键通过全部段落</td><td><code>resource</code></td></tr><tr><td><code>segment.retranslate_rejected</code></td><td>重译被驳回的段落</td><td><code>resource</code></td></tr><tr><td><code>resource.segment.update</code></td><td>手动编辑资源段落</td><td><code>segment</code></td></tr><tr><td><code>resource.segment.translation_preview.apply</code></td><td>应用预览翻译到段落</td><td><code>segment</code></td></tr><tr><td><code>glossary.sync_execute</code></td><td>执行术语表同步</td><td><code>glossary</code></td></tr><tr><td><code>quick_translate</code></td><td>即时翻译（不落库，仅记录用量与事件）</td><td>—</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">即时翻译为何也记录</p><p>即时翻译本身不落库译文，但仍会消耗 LLM 配额并可能触发限流。将其记入审计日志，便于管理员核算用量与排查异常。</p></div><p>随着功能迭代，动作列表可能扩展。前端对未知 <code>action</code> 会原样显示字符串，因此集成外部监控时建议按前缀（如 <code>job.</code>、<code>segment.</code>）做宽松匹配，而非精确等于。</p><h2 id="系统设置" tabindex="-1">系统设置 <a class="header-anchor" href="#系统设置" aria-label="Permalink to &quot;系统设置&quot;">​</a></h2><p><code>/admin/settings</code> 以扁平 <code>key → value</code>（均为字符串）的形式读写系统级配置，存储于数据库的 <code>system_settings</code> 表，用于跨重启持久化少量运行期参数。</p><ul><li><code>GET /admin/settings</code> —— 返回当前全部键值</li><li><code>PATCH /admin/settings</code> —— 传入待更新的键值对，仅覆盖提供的键，未传入的键保持不变</li></ul><div class="warning custom-block"><p class="custom-block-title">与配置文件的关系</p><p>此处的「系统设置」是数据库内的运行期参数，与 <code>linguaflow.yaml</code> / 环境变量是两套机制。YAML 与环境变量在启动时加载，决定监听端口、数据库、日志等基础设施行为；系统设置面向可在线调整的运行期参数。两者<strong>不会</strong>自动同步，请勿在此处期望修改端口或数据库连接。</p></div><p>具体可用的设置键随版本演进，以 Redoc 与实际接口返回为准。</p><h2 id="api-速览" tabindex="-1">API 速览 <a class="header-anchor" href="#api-速览" aria-label="Permalink to &quot;API 速览&quot;">​</a></h2><p>管理员接口统一挂在 <code>/api/v1/admin/*</code> 下，均需 <code>Bearer Token</code> 且要求 <code>role=admin</code>，否则返回 <code>403 forbidden</code>。</p><table tabindex="0"><thead><tr><th>方法</th><th>路径</th><th>说明</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/admin/users</code></td><td>列出用户（支持 <code>search</code> / <code>role</code> / <code>active</code> / <code>cursor</code> / <code>limit</code>）</td></tr><tr><td><code>POST</code></td><td><code>/admin/users</code></td><td>创建用户</td></tr><tr><td><code>GET</code></td><td><code>/admin/users/{userId}</code></td><td>获取用户详情</td></tr><tr><td><code>PATCH</code></td><td><code>/admin/users/{userId}</code></td><td>更新用户资料 / 角色 / 启用状态</td></tr><tr><td><code>DELETE</code></td><td><code>/admin/users/{userId}</code></td><td>停用用户</td></tr><tr><td><code>PUT</code></td><td><code>/admin/users/{userId}/password</code></td><td>重置密码</td></tr><tr><td><code>GET</code></td><td><code>/admin/stats</code></td><td>全局统计</td></tr><tr><td><code>GET</code></td><td><code>/admin/audit-logs</code></td><td>全局审计日志（<code>cursor</code> / <code>limit</code>）</td></tr><tr><td><code>GET</code></td><td><code>/admin/settings</code></td><td>读取系统设置</td></tr><tr><td><code>PATCH</code></td><td><code>/admin/settings</code></td><td>更新系统设置</td></tr></tbody></table><p>字段与响应结构的权威定义见 <a href="/LinguaFlow/zh/api/#openapi-规范">OpenAPI 规范</a> 与 Redoc。</p><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/LinguaFlow/zh/guide/modes.html">使用模式</a> — 服务器模式与初始管理员配置</li><li><a href="/LinguaFlow/zh/guide/configuration.html">配置文件与环境变量</a> — <code>registration.auto_admin</code> 等配置项</li><li><a href="/LinguaFlow/zh/api/">API 参考</a> — 接口总览与 Redoc 入口</li></ul>',42)])])}const m=d(a,[["render",r]]);export{p as __pageData,m as default};
